@st.cache_data(show_spinner="공공도서관 데이터를 불러오는 중입니다...")
def load_data():
    """main.py에 포함된 CP949 CSV를 읽습니다."""
    csv_bytes = gzip.decompress(base64.b64decode(DATA_GZIP_BASE64))
    data = pd.read_csv(BytesIO(csv_bytes), encoding="cp949", dtype={"도서관코드": str})
    for column in NUMERIC_COLUMNS + ["평가년도"]:
        if column in data.columns:
            data[column] = pd.to_numeric(data[column], errors="coerce")
    return data


def safe_silhouette(x, labels, ignore_noise=False):
    """실루엣 점수를 안전하게 계산합니다. DBSCAN은 노이즈(-1)를 제외합니다."""
    labels = np.asarray(labels)
    mask = labels != -1 if ignore_noise else np.ones(len(labels), dtype=bool)
    x_use = x[mask]
    y_use = labels[mask]
    unique_labels = np.unique(y_use)
    if len(unique_labels) < 2 or len(unique_labels) >= len(y_use):
        return np.nan
    try:
        sample_size = min(1000, len(y_use))
        return float(silhouette_score(
            x_use,
            y_use,
            sample_size=sample_size if len(y_use) > sample_size else None,
            random_state=42,
        ))
    except Exception:
        return np.nan


def display_cluster_label(value):
    value = int(value)
    return "노이즈" if value == -1 else f"군집 {value + 1}"


def prepare_data(data, features, exclude_no_borrow, use_log):
    work = data.copy()
    initial_rows = len(work)
    both_zero_count = int(((work["대출자수"] == 0) & (work["대출권수"] == 0)).sum())

    if exclude_no_borrow:
        work = work.loc[~((work["대출자수"] == 0) & (work["대출권수"] == 0))].copy()

    for column in features:
        work[column] = pd.to_numeric(work[column], errors="coerce")

    valid = work[features].notna().all(axis=1)
    valid &= (work[features] >= 0).all(axis=1)
    removed_invalid = int((~valid).sum())
    work = work.loc[valid].copy()

    raw_x = work[features].astype(float).copy()
    transformed_x = np.log1p(raw_x) if use_log else raw_x.copy()
    scaler = StandardScaler()
    scaled_x = scaler.fit_transform(transformed_x)

    info = {
        "initial_rows": initial_rows,
        "both_zero_count": both_zero_count,
        "removed_invalid": removed_invalid,
        "final_rows": len(work),
    }
    return work, raw_x, transformed_x, scaled_x, info


def cluster_metrics(x, labels, ignore_noise=False):
    labels = np.asarray(labels)
    cluster_labels = labels[labels != -1]
    cluster_ids, counts = np.unique(cluster_labels, return_counts=True)
    cluster_count = len(cluster_ids)
    noise_count = int(np.sum(labels == -1))
    assigned_count = len(labels) - noise_count
    coverage = assigned_count / len(labels) if len(labels) else 0.0
    min_cluster_size = int(counts.min()) if len(counts) else 0
    score = safe_silhouette(x, labels, ignore_noise=ignore_noise)
    return {
        "군집 수": cluster_count,
        "노이즈 수": noise_count,
        "군집 포함률(%)": coverage * 100,
        "가장 작은 군집": min_cluster_size,
        "최소 군집 비율(%)": min_cluster_size / len(labels) * 100 if len(labels) else 0,
        "실루엣 점수": score,
    }


def best_kmeans(x, max_k):
    best = None
    for candidate_k in range(2, max_k + 1):
        labels = KMeans(n_clusters=candidate_k, random_state=42, n_init=20).fit_predict(x)
        score = safe_silhouette(x, labels)
        if np.isfinite(score) and (best is None or score > best["score"]):
            best = {"k": candidate_k, "labels": labels, "score": score}
    if best is None:
        raise ValueError("K-Means 후보의 실루엣 점수를 계산하지 못했습니다.")
    return best


def best_hierarchical(x, max_k):
    best = None
    for candidate_k in range(2, max_k + 1):
        labels = AgglomerativeClustering(n_clusters=candidate_k, linkage="ward").fit_predict(x)
        score = safe_silhouette(x, labels)
        if np.isfinite(score) and (best is None or score > best["score"]):
            best = {"k": candidate_k, "labels": labels, "score": score}
    if best is None:
        raise ValueError("계층적 군집의 실루엣 점수를 계산하지 못했습니다.")
    return best


def calculate_elbow(x, max_k):
    """K-Means의 K별 군집 내 제곱합(inertia)을 계산합니다."""
    rows = []
    for candidate_k in range(2, max_k + 1):
        model = KMeans(n_clusters=candidate_k, random_state=42, n_init=20)
        model.fit(x)
        rows.append({"K": candidate_k, "군집 내 제곱합(SSE)": float(model.inertia_)})
    elbow_df = pd.DataFrame(rows)
    previous_sse = elbow_df["군집 내 제곱합(SSE)"].shift(1)
    elbow_df["직전 K 대비 감소량"] = previous_sse - elbow_df["군집 내 제곱합(SSE)"]
    elbow_df["직전 K 대비 감소율(%)"] = (
        elbow_df["직전 K 대비 감소량"] / previous_sse * 100
    )
    return elbow_df


def run_model_comparison(work, raw_x, scaled_x, max_k, baseline_k, eps, min_samples,
                         min_cluster_pct, min_coverage_pct):
    # K 선택 근거는 엘보 그래프에서 확인하고, 선택한 K로 베이스라인을 실행합니다.
    baseline_labels = KMeans(n_clusters=baseline_k, random_state=42, n_init=20).fit_predict(scaled_x)
    elbow_df = calculate_elbow(scaled_x, max_k)

    # 후보 1: K=2~max_k를 같은 실루엣 기준으로 비교해 K-Means 군집 수 선택
    km_best = best_kmeans(scaled_x, max_k)
    # 후보 2: 같은 K 탐색 범위에서 Ward 계층적 군집의 군집 수 선택
    hierarchical_best = best_hierarchical(scaled_x, max_k)
    # 후보 3: 사용자가 사이드바에서 정한 DBSCAN 거리·이웃 설정
    dbscan_labels = DBSCAN(eps=eps, min_samples=min_samples).fit_predict(scaled_x)

    labels_by_name = {
        BASELINE_NAME: baseline_labels,
        "K-Means 군집 수 탐색": km_best["labels"],
        "계층적 군집": hierarchical_best["labels"],
        "DBSCAN": dbscan_labels,
    }
    params = {
        BASELINE_NAME: f"K={baseline_k} (엘보 그래프를 참고해 선택), random_state=42",
        "K-Means 군집 수 탐색": f"선택된 K={km_best['k']} (탐색 범위 2~{max_k})",
        "계층적 군집": f"Ward 방식, 선택된 K={hierarchical_best['k']} (탐색 범위 2~{max_k})",
        "DBSCAN": f"eps={eps:.2f}, min_samples={min_samples}",
    }

    metric_rows = []
    for name, labels in labels_by_name.items():
        is_dbscan = name == "DBSCAN"
        metric = cluster_metrics(scaled_x, labels, ignore_noise=is_dbscan)
        metric_rows.append({"모델": name, "구분": "베이스라인" if name == BASELINE_NAME else "후보 모델",
                            "설정": params[name], **metric})
    comparison_df = pd.DataFrame(metric_rows)
    baseline_score = comparison_df.loc[comparison_df["모델"] == BASELINE_NAME, "실루엣 점수"].iloc[0]
    comparison_df["베이스라인 대비 점수 차이"] = comparison_df["실루엣 점수"] - baseline_score

    # 최종 후보 판단은 점수뿐 아니라 군집 포함률과 최소 군집 크기도 고려합니다.
    comparison_df["최종 후보 조건"] = (
        (comparison_df["군집 수"] >= 2)
        & (comparison_df["군집 포함률(%)"] >= min_coverage_pct)
        & (comparison_df["최소 군집 비율(%)"] >= min_cluster_pct)
        & comparison_df["실루엣 점수"].notna()
    )
    comparison_df.loc[comparison_df["모델"] == BASELINE_NAME, "최종 후보 조건"] = True

    display_df = work[DISPLAY_COLUMNS + ["도서관코드"] + NUMERIC_COLUMNS].copy()
    for name, labels in labels_by_name.items():
        display_df[name] = [display_cluster_label(value) for value in labels]

    pca_xy = PCA(n_components=2, random_state=42).fit_transform(scaled_x)
    pca_df = work[DISPLAY_COLUMNS].copy()
    pca_df["주성분 1"] = pca_xy[:, 0]
    pca_df["주성분 2"] = pca_xy[:, 1]
    for name, labels in labels_by_name.items():
        pca_df[name] = [display_cluster_label(value) for value in labels]

    return labels_by_name, comparison_df, display_df, pca_df, params, elbow_df


def make_cluster_summary(raw_x, labels, features):
    temp = raw_x.copy()
    temp["군집"] = [display_cluster_label(value) for value in labels]
    summary = temp.groupby("군집", sort=False)[features].agg(["count", "mean", "median"])
    summary.columns = [f"{feature}_{stat}" for feature, stat in summary.columns]
    return summary.reset_index()


def format_score(value):
    return f"{value:.3f}" if pd.notna(value) else "계산 불가"


